class ActiveQueue(private val servant: MQServant) {
    private val requests = Channel<suspend () -> Unit>(capacity = 64)
    private val scope = CoroutineScope(Dispatchers.Default.limitedParallelism(1))
    init { scope.launch { for (run in requests) run() } }   // scheduler
    suspend fun put(msg: Message): Unit = defer { servant.putI(msg) }
    private suspend fun defer(block: suspend () -> Unit) {
        val done = CompletableDeferred<Unit>()
        requests.send {
            try {
                block()
                done.complete(Unit)
            } catch (t: CancellationException) {
                done.cancel(t)
                throw t
            } catch (t: Throwable) {
                done.completeExceptionally(t)
            }
        }
        done.await()                                        // future rendezvous
    }
}
